input.command:
python3 - <<'EOF'
import json
specs=[(33,"Ab 2",2),(39,"Aidh, Es 1",12),(46,"Al 2",3),(54,"An 2, Eno, Ono",1),(101,"B.r.q",4),(126,"Dheigh, Dhigha",1),(311,"Leudh, Rei",13)]
for p,root,nid in specs:
    d=json.load(open(f"data/verification/page-{p}.json"))
    for e in d["entries"]:
        if e["root"]==root:
            for n in e.get("nodes",[]):
                if n["id"]==nid:
                    print("="*80); print("PAGE",p,root,"node",nid)
                    print(json.dumps(n,ensure_ascii=False,indent=1))
EOF

